#![forbid(unsafe_code)]

//! ARM (AArch64) backend using the shared ISA framework.
//!
//! Mode, feature, and backend types are generated by `define_arch!`.
//! The `ArchitectureBackend` trait impl is also generated by the macro
//! via `backend_impl { ... }`, delegating to standalone functions below.

use robustone_core::ir::{ArchitectureId, Operand, RegisterId};
use robustone_core::types::error::{DecodeErrorKind, DisasmError};
use robustone_isa::{DecodeProfile, FormatSpec, InstructionRead, InstructionSpec};

// ---------------------------------------------------------------------------
// Field enum
// ---------------------------------------------------------------------------

/// AArch64 instruction fields used by format specs and field extractors.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArmField {
    // General-purpose registers
    Rd,
    Rn,
    Rm,
    Ra,
    Rt,
    Rt2,
    Rs,
    // Immediates
    Imm9,
    Imm12,
    Imm16,
    Imm19,
    Imm26,
    Immhi,
    Immlo,
    Imm7,
    Imm3,
    Option,
    Cond,
    Shift,
    Imm6,
    Hw,
    N,
    Immr,
    Imms,
    // FP / SIMD
    Ftype,
    Opcode,
    Size,
    Q,
    U,
    L,
    M,
    H,
}

// ---------------------------------------------------------------------------
// Registers
// ---------------------------------------------------------------------------

robustone_isa_macros::define_registers! {
    arch = Arm;
    bank Gpr {
        count = 31;
        base_id = 0;
        canonical = "x{n}";
    }
    bank Vec {
        count = 32;
        base_id = 64;
        canonical = "v{n}";
    }
    bank Pred {
        count = 16;
        base_id = 128;
        canonical = "p{n}";
    }
    bank ZVec {
        count = 32;
        base_id = 160;
        canonical = "z{n}";
    }
    bank Za {
        count = 1;
        base_id = 192;
        canonical = "za{n}";
    }
    bank Sys {
        count = 4096;
        base_id = 512;
        canonical = "sys{n}";
    }
}

// ---------------------------------------------------------------------------
// Architecture definition
// ---------------------------------------------------------------------------

robustone_isa_macros::define_arch! {
    pub arch Arm {
        word = u32;
        endian = little;
        instruction_length = fixed(4);
        modes { AArch64 = "aarch64"; };
        features: u64 {
            BASE = 0;
            FP = 1;
            SIMD = 2;
            CRYPTO = 3;
            ATOMICS = 4;
            SYSTEM = 5;
            SVE = 6;
            SME = 7;
            RCPC = 8;
            PAUTH = 9;
            BTI = 10;
            MTE = 11;
            BF16 = 12;
            CSSC = 13;
            FP8DOT2 = 14;
            FAMINMAX = 15;
            LUT = 16;
            FP8 = 17;
            FP8FMA = 18;
        };
        registers = arm_registers;
        formats = arm_formats;
        specs = arm_specs;
        render = ArmRenderPolicy;
        backend_impl {
            field = ArmField;
            register_class = ArmRegisterClass;
            architecture_id = ArchitectureId::AArch64;
            read_instruction = arm_read_instruction;
            lookup = arm_lookup;
            lower_register = arm_lower_register;
            extract_field = arm_extract_field;
            apply_aliases = arm_apply_aliases;
        }
    }
}

// ---------------------------------------------------------------------------
// Spec modules
// ---------------------------------------------------------------------------

/// Base integer data-processing instruction specs (arithmetic, logical, bitfield, etc.).
pub mod specs_base {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_base.rs");
}
/// Branch instruction specs (B, BL, B.cond, CBZ, CBNZ, TBZ, TBNZ).
pub mod specs_branch {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_branch.rs");
}
/// Load/store instruction specs (immediate, literal, pair, atomic).
pub mod specs_loadstore {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_loadstore.rs");
}
/// Load/store register offset instruction specs.
/// Kept in a separate slice because their masks overlap with unsigned-immediate
/// specs; priority-based resolution in `arm_lookup` handles selection at runtime.
pub mod specs_loadstore_regoffset {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_loadstore_regoffset.rs");
}
/// Scalar floating-point data-processing specs (1-source, 2-source, 3-source, comparison, conversion).
pub mod specs_scalar_fp {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_scalar_fp.rs");
}
/// System instruction specs (NOP, SVC, BRK, barriers, MSR/MRS).
pub mod specs_system {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_system.rs");
}
/// Advanced SIMD vector instruction specs (three same, two-reg misc, across lanes, copy/extract, indexed element, modified immediate, shift immediate, table lookup, crypto).
pub mod specs_vector {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_vector.rs");
}
/// Generated AArch64 instruction specs.
pub mod generated;

/// Concatenated slices of all AArch64 instruction specs for validation and lookup.
pub static ALL_SPEC_SLICES: &[&[InstructionSpec<ArmBackend>]] = &[
    specs_base::SPECS,
    specs_branch::SPECS,
    specs_loadstore::SPECS,
    specs_loadstore_regoffset::SPECS,
    specs_scalar_fp::SPECS,
    specs_system::SPECS,
    specs_vector::SPECS,
];

fn all_arm_specs() -> impl Iterator<Item = &'static InstructionSpec<ArmBackend>> {
    ALL_SPEC_SLICES
        .iter()
        .chain(generated::ALL_GENERATED_SPEC_SLICES.iter())
        .flat_map(|s| s.iter())
}

// ---------------------------------------------------------------------------
// Backend functions
// ---------------------------------------------------------------------------

/// Read a single 32-bit little-endian AArch64 instruction from bytes.
fn arm_read_instruction(bytes: &[u8]) -> Result<InstructionRead<u32>, DisasmError> {
    if bytes.len() < 4 {
        return Err(DisasmError::decode_failure(
            DecodeErrorKind::NeedMoreBytes,
            Some(ArchitectureId::AArch64.as_str().to_string()),
            "need 4 bytes",
        ));
    }
    let word = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);
    Ok(InstructionRead {
        raw: word,
        length: 4,
    })
}

/// Look up the instruction spec matching `word` within the enabled feature set.
/// Uses hierarchical op0 pre-filtering to reduce linear search cost.
fn arm_lookup(
    word: u32,
    profile: &DecodeProfile<ArmBackend>,
) -> Option<&'static InstructionSpec<ArmBackend>> {
    let op0 = ((word >> 25) & 0xF) as u8;

    // Hierarchical dispatch: pre-filter by op0 range before linear match.
    // Higher-priority (more specific) specs are tried first, with enabled
    // feature matches preferred over disabled extension candidates.
    all_arm_specs()
        .filter(|spec| {
            let spec_op0 = ((spec.pattern().value >> 25) & 0xF) as u8;
            let spec_mask = ((spec.pattern().mask >> 25) & 0xF) as u8;
            let op0_matches = (op0 & spec_mask) == spec_op0;

            op0_matches && (word & spec.pattern().mask) == spec.pattern().value
        })
        .fold(None, |best, spec| match best {
            None => Some(spec),
            Some(current) => {
                let spec_key = (profile.features.contains(spec.features()), spec.priority());
                let current_key = (
                    profile.features.contains(current.features()),
                    current.priority(),
                );
                if spec_key > current_key {
                    Some(spec)
                } else {
                    Some(current)
                }
            }
        })
}

/// Lower a raw register number into a `RegisterId` for the given register class.
fn arm_lower_register(
    class: ArmRegisterClass,
    raw: u32,
    _profile: &DecodeProfile<ArmBackend>,
) -> RegisterId {
    match lower_register(class, raw) {
        Ok(id) => RegisterId::aarch64(id),
        Err(_) => RegisterId::aarch64(raw),
    }
}

/// Extract the value of `field` from `word` according to the format definition.
fn arm_extract_field(
    word: u32,
    format: &FormatSpec<ArmField>,
    field: ArmField,
) -> Result<u32, DisasmError> {
    // Search format fields for matching field type and extract bits
    for f in format.fields() {
        if f.field_type() == field {
            let mask = ((1u64 << f.length()) - 1) as u32;
            return Ok((word >> f.start()) & mask);
        }
    }
    Err(DisasmError::decode_failure(
        DecodeErrorKind::InvalidField,
        Some(ArchitectureId::AArch64.as_str().to_string()),
        format!("field {:?} not found in format {}", field, format.name()),
    ))
}

// ---------------------------------------------------------------------------
// Alias / operand rewrite
// ---------------------------------------------------------------------------

/// Rewrite decoded operands and mnemonics to match AArch64 assembly conventions.
///
/// Handles SIMD arrangement suffixes, scalar FP register names, indexed element
/// notation, shift immediates, modified immediates, and various instruction aliases.
fn arm_apply_aliases(decoded: &mut robustone_core::ir::DecodedInstruction) {
    if decoded.raw_bytes.len() < 4 {
        return;
    }
    let word = u32::from_le_bytes([
        decoded.raw_bytes[0],
        decoded.raw_bytes[1],
        decoded.raw_bytes[2],
        decoded.raw_bytes[3],
    ]);

    let opcode_id = decoded.opcode_id.clone().unwrap_or_default();

    if matches!(opcode_id.as_str(), "FCVT_Z4Z_STOB" | "FCVTN_Z4Z_STOB") {
        apply_sve_fp8_range4_narrow_aliases(decoded, word);
        return;
    }

    if matches!(
        opcode_id.as_str(),
        "FCVT_Z2Z_HTOB" | "BFCVT_Z2Z_HTOB" | "FCVT_Z2Z_STOH" | "BFCVT_Z2Z_STOH"
    ) {
        apply_sve_fp8_group_narrow_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("FAMIN_ZPMZ_") || opcode_id.starts_with("FAMAX_ZPMZ_") {
        apply_sve_faminmax_pred_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("F1CVT_ZZ_BTOH")
        || opcode_id.starts_with("F1CVTLT_ZZ_BTOH")
        || opcode_id.starts_with("F2CVT_ZZ_BTOH")
        || opcode_id.starts_with("F2CVTLT_ZZ_BTOH")
        || opcode_id.starts_with("BF1CVT_ZZ_BTOH")
        || opcode_id.starts_with("BF1CVTLT_ZZ_BTOH")
        || opcode_id.starts_with("BF2CVT_ZZ_BTOH")
        || opcode_id.starts_with("BF2CVTLT_ZZ_BTOH")
    {
        apply_sve_fp8_single_conversion_aliases(decoded, word);
        return;
    }

    if matches!(
        opcode_id.as_str(),
        "F1CVT_2ZZ_BTOH"
            | "F1CVTL_2ZZ_BTOH"
            | "F2CVTL_2ZZ_BTOH"
            | "BF1CVT_2ZZ_BTOH"
            | "BF1CVTL_2ZZ_BTOH"
            | "F2CVT_2ZZ_BTOH"
            | "BF2CVTL_2ZZ_BTOH"
            | "BF2CVT_2ZZ_BTOH"
    ) {
        apply_sve_fp8_conversion_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADD_VG2_M2ZZ_")
        || opcode_id.starts_with("ADD_VG2_M2Z2Z_")
        || opcode_id.starts_with("ADD_VG4_M4ZZ_")
        || opcode_id.starts_with("ADD_VG4_M4Z4Z_")
    {
        apply_sme_za_group_unary_r_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("FVDOT") && opcode_id.contains("_M") {
        apply_sme_fvdot_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("FDOT_VG") && opcode_id.contains("_M") {
        apply_sme_fdot_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADD_VG2_M2Z_")
        || opcode_id.starts_with("ADD_VG4_M4Z_")
        || opcode_id.starts_with("BFADD_VG")
        || opcode_id.starts_with("FADD_VG")
    {
        apply_sme_za_group_unary_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADD_VG2_2ZZ_") || opcode_id.starts_with("ADD_VG4_4ZZ_") {
        apply_sme_z_group_binary_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "RDSVLI_XI" {
        apply_sme_read_vl_aliases(decoded, word, "rdsvl");
        return;
    }

    if opcode_id == "MSRPSTATESVCRIMM1" {
        apply_sme_svcr_aliases(decoded, word);
        return;
    }

    if opcode_id == "ZERO_M" {
        apply_sme_zero_aliases(decoded, word);
        return;
    }

    if opcode_id == "LDR_ZA" || opcode_id == "STR_ZA" {
        apply_sme_za_spill_fill_aliases(decoded, word, &opcode_id);
        return;
    }

    // Load/store: combine base register and offset into memory operand text.
    if is_loadstore_opcode(&opcode_id) {
        apply_loadstore_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_prefetch_opcode(&opcode_id) {
        apply_sve_prefetch_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_tuple_memory_opcode(&opcode_id) {
        apply_sve_tuple_memory_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_fp_immediate_dup_opcode(&opcode_id) {
        apply_sve_fp_immediate_dup_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_exact_fp_immediate_opcode(&opcode_id) {
        apply_sve_exact_fp_immediate_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_addsub_immediate_opcode(&opcode_id) {
        apply_sve_addsub_immediate_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADR_") {
        apply_sve_adr_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_pattern_count_opcode(&opcode_id) {
        apply_sve_pattern_count_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve2_aes_opcode(&opcode_id) {
        apply_sve2_aes_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_predicated_complex_mla_opcode(&opcode_id) {
        apply_sve_predicated_complex_mla_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_xar_opcode(&opcode_id) {
        apply_sve_xar_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_indexed_complex_rotate_opcode(&opcode_id) {
        apply_sve_indexed_complex_rotate_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_narrow_shift_immediate_opcode(&opcode_id) {
        apply_sve_narrow_shift_immediate_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.contains("_ZZR_")
        && (opcode_id.starts_with("LDNT1") || opcode_id.starts_with("STNT1"))
    {
        apply_sve_nt1_vector_address_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_while_compare_opcode(&opcode_id) {
        apply_sve_while_compare_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("TBL_ZZZZ_") {
        apply_sve_tbl_two_register_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SPLICE_ZPZZ_") {
        apply_sve_splice_vector_list_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SM4E_ZZZ_") {
        apply_sve_sm4e_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("MATCH_PPZZZ_") || opcode_id.starts_with("NMATCH_PPZZZ_") {
        apply_sve_match_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "HISTSEG_ZZZ" {
        apply_sve_histseg_aliases(decoded, word);
        return;
    }

    if opcode_id.starts_with("HISTCNT_ZPZZZ_") {
        apply_sve_histcnt_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("PMULLB_ZZZ_") || opcode_id.starts_with("PMULLT_ZZZ_") {
        apply_sve_pmull_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_indexed_mla_opcode(&opcode_id) {
        apply_sve_indexed_mla_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_long_mla_opcode(&opcode_id) {
        apply_sve_long_mla_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_wide_addsub_opcode(&opcode_id) {
        apply_sve_wide_addsub_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_adalp_opcode(&opcode_id) {
        apply_sve_adalp_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_shift_left_long_opcode(&opcode_id) {
        apply_sve_shift_left_long_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_extract_narrow_opcode(&opcode_id) {
        apply_sve_extract_narrow_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_convert_long_narrow_opcode(&opcode_id) {
        apply_sve_convert_long_narrow_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "EXT_ZZI_B" {
        apply_sve_ext_vector_list_aliases(decoded, word);
        return;
    }

    if is_sve_zpmzz_pairwise_opcode(&opcode_id) {
        apply_sve_zpmzz_pairwise_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_complex_mla_opcode(&opcode_id) {
        apply_sve_complex_mla_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_complex_dot_opcode(&opcode_id) {
        apply_sve_complex_dot_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_complex_rotate_add_opcode(&opcode_id) {
        apply_sve_complex_rotate_add_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADD_ZPMZ_")
        || opcode_id.starts_with("ASR_WIDE_ZPMZ_")
        || opcode_id.starts_with("LSL_WIDE_ZPMZ_")
        || opcode_id.starts_with("LSR_WIDE_ZPMZ_")
        || opcode_id.starts_with("ASR_ZPMZ_")
        || opcode_id.starts_with("LSL_ZPMZ_")
        || opcode_id.starts_with("LSR_ZPMZ_")
    {
        apply_sve_zpmz_binary_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADD_ZZZ_")
        || is_sve_zzz_vector_opcode(&opcode_id)
        || opcode_id.starts_with("ASR_WIDE_ZZZ_")
        || opcode_id.starts_with("LSL_WIDE_ZZZ_")
        || opcode_id.starts_with("LSR_WIDE_ZZZ_")
        || opcode_id.starts_with("ASR_ZZZ_")
        || opcode_id.starts_with("LSL_ZZZ_")
        || opcode_id.starts_with("LSR_ZZZ_")
    {
        apply_sve_zzz_aliases(decoded, word, &opcode_id);
        return;
    }

    if is_sve_zzzz_opcode(&opcode_id) {
        apply_sve_zzzz_aliases(decoded, word);
        return;
    }

    if opcode_id.ends_with("_ZPMZ_B")
        || opcode_id.ends_with("_ZPMZ_H")
        || opcode_id.ends_with("_ZPMZ_S")
        || opcode_id.ends_with("_ZPMZ_D")
    {
        apply_sve_zpmz_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "ADDPL_XXI" || opcode_id == "ADDVL_XXI" {
        apply_sve_vl_add_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "ADDSPL_XXI" || opcode_id == "ADDSVL_XXI" {
        apply_sme_streaming_vl_add_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("EXTRACT_ZPMXI_") || opcode_id.starts_with("INSERT_MXIPZ_") {
        apply_sme_mova_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("PSEL_PPPRI_") {
        apply_sme_psel_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("LD1_MXIPXX_") || opcode_id.starts_with("ST1_MXIPXX_") {
        apply_sme_tile_vector_load_store_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ADDHA_MPPZ_") || opcode_id.starts_with("ADDVA_MPPZ_") {
        apply_sme_addhv_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_MOVT_") {
        apply_sme_movt_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FMOPA_") || is_sme_mopa_opcode(&opcode_id) {
        apply_sme_fmopa_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FMLAL_") || opcode_id.starts_with("SME_FMLALL_") {
        apply_sme_fmlal_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_LUTI4_") {
        apply_sme_luti4_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FSCALE_") {
        apply_sme_fscale_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FAMAX_") || opcode_id.starts_with("SME_FAMIN_") {
        apply_sme_faminmax_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FVDOT") {
        apply_sme_fvdot_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SME_FDOT_") {
        apply_sme_fdot_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASR_ZZI_")
        || opcode_id.starts_with("LSL_ZZI_")
        || opcode_id.starts_with("LSR_ZZI_")
        || opcode_id.starts_with("SSRA_ZZI_")
        || opcode_id.starts_with("USRA_ZZI_")
        || opcode_id.starts_with("SRSRA_ZZI_")
        || opcode_id.starts_with("URSRA_ZZI_")
        || opcode_id.starts_with("ASRD_ZPMI_")
        || opcode_id.starts_with("ASR_ZPMI_")
        || opcode_id.starts_with("LSL_ZPMI_")
        || opcode_id.starts_with("LSR_ZPMI_")
        || opcode_id.starts_with("SQSHL_ZPMI_")
        || opcode_id.starts_with("SQSHLU_ZPMI_")
        || opcode_id.starts_with("UQSHL_ZPMI_")
        || opcode_id.starts_with("SRSHR_ZPMI_")
        || opcode_id.starts_with("URSHR_ZPMI_")
    {
        apply_sve_shift_immediate_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SLI_ZZI_") || opcode_id.starts_with("SRI_ZZI_") {
        apply_sve_shift_insert_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SVE_MOVPRFX_") || opcode_id.starts_with("MOVPRFX_") {
        apply_sve_movprfx_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SVE_FAMAX_PRED_") || opcode_id.starts_with("SVE_FAMIN_PRED_") {
        apply_sve_faminmax_pred_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("SVE_FP8_") {
        apply_sve_fp8_conversion_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASIMD_FP8_FMLA") {
        apply_asimd_fp8_fma_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASIMD_FSCALE_") {
        apply_asimd_fscale_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id == "ASIMD_FP8_FCVTN" {
        apply_asimd_fp8_fcvtn_aliases(decoded, word);
        return;
    }

    if opcode_id.ends_with("CVTL") || opcode_id.ends_with("CVTL2") {
        apply_asimd_fp8_conversion_aliases(decoded, &opcode_id);
        return;
    }

    if opcode_id == "ASIMD_LUTI2" || opcode_id == "ASIMD_LUTI4" {
        apply_asimd_lut_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASIMD_FDOT_VEC_") {
        apply_asimd_fdot_vector_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASIMD_FDOT_LANE_") {
        apply_asimd_fdot_lane_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("ASIMD_FAMAX_VEC_") || opcode_id.starts_with("ASIMD_FAMIN_VEC_") {
        apply_asimd_faminmax_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("VEC_") {
        // Special-case SHA three-register: mixed scalar/vector operands.
        if is_sha_three_reg_opcode(&opcode_id) {
            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    match (opcode_id.as_str(), i) {
                        ("VEC_SHA1C" | "VEC_SHA1P" | "VEC_SHA1M", 1) => {
                            *op = Operand::Text {
                                value: format!("s{}", reg_num),
                            };
                        }
                        ("VEC_SHA1C" | "VEC_SHA1P" | "VEC_SHA1M", 0)
                        | ("VEC_SHA256H" | "VEC_SHA256H2", 0)
                        | ("VEC_SHA256H" | "VEC_SHA256H2", 1) => {
                            *op = Operand::Text {
                                value: format!("q{}", reg_num),
                            };
                        }
                        _ => {
                            *op = Operand::Text {
                                value: format!("v{}.4s", reg_num),
                            };
                        }
                    }
                }
            }
            return;
        }

        // Table lookup: render register list for Rn and .16b for Rd/Rm.
        if is_table_lookup_opcode(&opcode_id) {
            let len = ((word >> 13) & 0x3) as usize;
            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    match i {
                        0 | 2 => {
                            *op = Operand::Text {
                                value: format!("v{}.16b", reg_num),
                            };
                        }
                        1 => {
                            let mut list = String::new();
                            list.push('{');
                            for j in 0..=len {
                                if j > 0 {
                                    list.push_str(", ");
                                }
                                list.push_str(&format!("v{}.16b", reg_num + j as u32));
                            }
                            list.push('}');
                            *op = Operand::Text { value: list };
                        }
                        _ => {}
                    }
                }
            }
            return;
        }

        // Copy/Extract SIMD instructions: DUP, INS, EXT, SMOV, UMOV.
        if is_copy_extract_opcode(&opcode_id) {
            let q = ((word >> 30) & 0x1) as u8;
            let imm5 = ((word >> 16) & 0x1F) as u8;
            let size = simd_element_size_from_imm5(imm5);
            let arr = vec_arrangement_suffix(size, q);
            let elem = element_type_suffix(size);
            let elem_index = imm5 >> (size + 1);

            match opcode_id.as_str() {
                "VEC_DUP_ELEMENT" => {
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = match i {
                                0 => Operand::Text {
                                    value: format!("v{}{}", reg_num, arr),
                                },
                                1 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                },
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_DUP_GENERAL" => {
                    let is_64bit = size == 3;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                        {
                            *op = match i {
                                0 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}{}", reg_num, arr),
                                    }
                                }
                                1 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_INS_GENERAL" => {
                    let is_64bit = size == 3;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                        {
                            *op = match i {
                                0 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                1 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_INS_ELEMENT" => {
                    let bits14_11 = ((word >> 11) & 0xF) as u8;
                    let src_index = bits14_11 >> size;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = match i {
                                0 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                },
                                1 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, src_index),
                                },
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_SMOV" => {
                    let is_64bit = q == 1;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                        {
                            *op = match i {
                                0 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                1 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_UMOV" => {
                    let is_64bit = q == 1 && size == 3;
                    let is_mov_alias = (q == 0 && size == 2) || (q == 1 && size == 3);
                    if is_mov_alias {
                        decoded.mnemonic = "mov".to_string();
                    }
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                        {
                            *op = match i {
                                0 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                1 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_EXT" => {
                    let ext_arr = if q == 1 { ".16b" } else { ".8b" };
                    let imm4 = ((word >> 11) & 0xF) as u8;
                    for op in &mut decoded.operands {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::AArch64
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = Operand::Text {
                                value: format!("v{}{}", reg_num, ext_arr),
                            };
                        }
                    }
                    decoded.operands.push(Operand::Immediate {
                        value: imm4 as i64,
                        unsigned_mask: 0xF,
                    });
                }
                _ => {}
            }
            return;
        }

        // Indexed Element SIMD instructions.
        // FMLAL2 indexed element: special handling because encoding uses size=2
        // but operates on H (16-bit) elements.
        if opcode_id == "VEC_FMLAL2_INDEXED" {
            let q = ((word >> 30) & 0x1) as u8;
            let h = ((word >> 11) & 0x1) as u8;
            let l = ((word >> 21) & 0x1) as u8;
            let bit20 = ((word >> 20) & 0x1) as u8;
            let index = ((h as u32) << 2) | ((l as u32) << 1) | (bit20 as u32);
            let rd_suffix = if q == 0 { ".2s" } else { ".4s" };
            let rn_suffix = if q == 0 { ".2h" } else { ".4h" };

            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    let adjusted_reg = if i == 2 { reg_num & 0xF } else { reg_num };
                    *op = match i {
                        0 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rd_suffix),
                        },
                        1 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rn_suffix),
                        },
                        2 => Operand::Text {
                            value: format!("v{}.h[{}]", adjusted_reg, index),
                        },
                        _ => continue,
                    };
                }
            }
            return;
        }

        if is_indexed_element_opcode(&opcode_id) {
            let size = ((word >> 22) & 0x3) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let h = ((word >> 11) & 0x1) as u8;
            let l = ((word >> 21) & 0x1) as u8;
            let bit20 = ((word >> 20) & 0x1) as u8;

            // Compute element index based on size. H/FP16 indexed encodings use
            // H:L:M lane bits even for 64-bit vector forms in the smoke corpus.
            let index = match size {
                0 | 1 => (h << 2) | (l << 1) | bit20,
                2 => (h << 1) | l, // S: {H, L}
                3 => h,            // D: {H}
                _ => 0,
            };

            // Compute arrangement suffix for Rd and Rn.
            let is_fp = is_fp_indexed_opcode(&opcode_id);
            let rn_suffix = if is_fp {
                fp_indexed_arrangement_suffix(size, q)
            } else {
                vec_arrangement_suffix(size, q)
            };

            // For long operations, destination is wider.
            let is_long = is_long_indexed_opcode(&opcode_id);
            let rd_suffix = if is_long {
                match size {
                    1 => ".4s", // H -> S
                    2 => ".2d", // S -> D
                    _ => rn_suffix,
                }
            } else {
                rn_suffix
            };

            // Widening instructions use a "2" suffix when Q=1.
            if is_long && q == 1 {
                decoded.mnemonic.push('2');
            }

            // Element type suffix for indexed register.
            let elem = match size {
                0 => "h", // FP16 uses h element
                1 => "h",
                2 => "s",
                3 => "d",
                _ => "",
            };

            // For H/FP16 elements (size < 2), Rm uses only 4 bits (bits 19:16)
            // and bit 20 (M) is part of the element index. For S/D elements
            // (size >= 2), Rm uses 5 bits {M, Rm[3:0]}.
            let rm_4bit_only = size < 2;

            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    // Mask Rm to 4 bits only for H/FP16 element sizes.
                    let adjusted_reg = if i == 2 && rm_4bit_only {
                        reg_num & 0xF
                    } else {
                        reg_num
                    };
                    *op = match i {
                        0 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rd_suffix),
                        },
                        1 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rn_suffix),
                        },
                        2 => Operand::Text {
                            value: format!("v{}.{}[{}]", adjusted_reg, elem, index),
                        },
                        _ => continue,
                    };
                }
            }
            return;
        }

        // Advanced SIMD Modified Immediate.
        if is_modified_imm_opcode(&opcode_id) {
            let op = ((word >> 29) & 0x1) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let cmode = ((word >> 12) & 0xF) as u8;
            let a = ((word >> 18) & 0x1) as u8;
            let b = ((word >> 17) & 0x1) as u8;
            let c = ((word >> 16) & 0x1) as u8;
            let d = ((word >> 9) & 0x1) as u8;
            let e = ((word >> 8) & 0x1) as u8;
            let f = ((word >> 7) & 0x1) as u8;
            let g = ((word >> 6) & 0x1) as u8;
            let h = ((word >> 5) & 0x1) as u8;
            let imm8 =
                (a << 7) | (b << 6) | (c << 5) | (d << 4) | (e << 3) | (f << 2) | (g << 1) | h;
            let rd = (word & 0x1F) as u8;

            // Determine mnemonic and arrangement.
            let (mnemonic, arr_suffix, is_scalar) = match (op, cmode) {
                // movi: op=0, cmode even (including 14)
                (0, c) if c < 15 && c % 2 == 0 => {
                    ("movi", modified_imm_arrangement(cmode, q, op), false)
                }
                // orr: op=0, cmode odd
                (0, c) if c < 15 && c % 2 == 1 => {
                    ("orr", modified_imm_arrangement(cmode, q, op), false)
                }
                // fmov: op=0, cmode=15
                (0, 15) => ("fmov", modified_imm_fp_arrangement(q, op), false),
                // mvni: op=1, cmode even < 14
                (1, c) if c < 14 && c % 2 == 0 => {
                    ("mvni", modified_imm_arrangement(cmode, q, op), false)
                }
                // bic: op=1, cmode odd < 14
                (1, c) if c < 14 && c % 2 == 1 => {
                    ("bic", modified_imm_arrangement(cmode, q, op), false)
                }
                // movi 64-bit: op=1, cmode=14
                (1, 14) => ("movi", modified_imm_arrangement(cmode, q, op), q == 0),
                // fmov D: op=1, cmode=15
                (1, 15) => ("fmov", modified_imm_fp_arrangement(q, op), false),
                _ => ("movi", "", false),
            };

            decoded.mnemonic = mnemonic.to_string();

            // Format immediate operand.
            let imm_text = if cmode == 14 && op == 1 {
                // 64-bit immediate: each bit of imm8 expands to a byte.
                let imm64 = ((a as u64) * 0xFF00000000000000)
                    | ((b as u64) * 0x00FF000000000000)
                    | ((c as u64) * 0x0000FF0000000000)
                    | ((d as u64) * 0x000000FF00000000)
                    | ((e as u64) * 0x00000000FF000000)
                    | ((f as u64) * 0x0000000000FF0000)
                    | ((g as u64) * 0x000000000000FF00)
                    | ((h as u64) * 0x00000000000000FF);
                format!("#0x{:016x}", imm64)
            } else if cmode == 15 {
                // FP immediate.
                let fp_val = fp_expand_imm(imm8, op, q);
                format!("#{:.8}", fp_val)
            } else {
                // Integer immediate with optional shift.
                let shift = modified_imm_shift(cmode);
                if shift == 0 {
                    format!("#{}", imm8)
                } else {
                    let shift_type = if cmode >= 12 { "msl" } else { "lsl" };
                    format!("#{}, {} #{}", imm8, shift_type, shift)
                }
            };

            // Build operand text.
            let reg_text = if is_scalar {
                format!("d{}", rd)
            } else {
                format!("v{}{}", rd, arr_suffix)
            };

            decoded.operands = vec![
                Operand::Text { value: reg_text },
                Operand::Text { value: imm_text },
            ];
            return;
        }

        // Advanced SIMD Vector Shift Immediate.
        if is_shift_imm_opcode(&opcode_id) {
            let u = ((word >> 29) & 0x1) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let opcode = ((word >> 11) & 0x1F) as u8;
            let immh = ((word >> 19) & 0xF) as u8;
            let immb = ((word >> 16) & 0x7) as u8;
            let immh_immb = (immh << 3) | immb;
            let rd = (word & 0x1F) as u8;
            let rn = ((word >> 5) & 0x1F) as u8;

            let esize = shift_imm_esize(immh);
            if esize == 0 {
                return;
            }

            // Determine if this is a right shift, left shift, narrowing, or widening.
            let (mnemonic, src_esize, dest_esize, is_narrowing, is_widening) = match (opcode, u) {
                // Basic right shifts
                (0b00000, 0) => ("sshr", esize, esize, false, false),
                (0b00000, 1) => ("ushr", esize, esize, false, false),
                (0b00010, 0) => ("ssra", esize, esize, false, false),
                (0b00010, 1) => ("usra", esize, esize, false, false),
                (0b00100, 0) => ("srshr", esize, esize, false, false),
                (0b00100, 1) => ("urshr", esize, esize, false, false),
                (0b00110, 0) => ("srsra", esize, esize, false, false),
                (0b00110, 1) => ("ursra", esize, esize, false, false),
                (0b01000, 1) => ("sri", esize, esize, false, false),
                // Left shifts
                (0b01010, 0) => ("shl", esize, esize, false, false),
                (0b01010, 1) => ("sli", esize, esize, false, false),
                (0b01100, 1) => ("sqshlu", esize, esize, false, false),
                (0b01110, 0) => ("sqshl", esize, esize, false, false),
                (0b01110, 1) => ("uqshl", esize, esize, false, false),
                // Narrowing right shifts
                (0b10000, 0) => ("shrn", esize * 2, esize, true, false),
                (0b10000, 1) => ("sqshrun", esize * 2, esize, true, false),
                (0b10001, 0) => ("rshrn", esize * 2, esize, true, false),
                (0b10001, 1) => ("sqrshrun", esize * 2, esize, true, false),
                (0b10010, 0) => ("sqshrn", esize * 2, esize, true, false),
                (0b10010, 1) => ("uqshrn", esize * 2, esize, true, false),
                (0b10011, 0) => ("sqrshrn", esize * 2, esize, true, false),
                (0b10011, 1) => ("uqrshrn", esize * 2, esize, true, false),
                // Widening left shifts
                (0b10100, 0) => ("sshll", esize, esize * 2, false, true),
                (0b10100, 1) => ("ushll", esize, esize * 2, false, true),
                _ => ("", esize, esize, false, false),
            };

            if mnemonic.is_empty() {
                return;
            }

            decoded.mnemonic = if (is_narrowing || is_widening) && q == 1 {
                format!("{}2", mnemonic)
            } else {
                mnemonic.to_string()
            };

            // Compute shift amount.
            let shift = if is_widening {
                // Widening: left shift, amount = immh:immb - esize
                immh_immb - esize
            } else if is_narrowing {
                // Narrowing: right shift, amount = 2 * esize - immh:immb
                (2 * esize) - immh_immb
            } else if matches!(mnemonic, "shl" | "sli" | "sqshl" | "uqshl" | "sqshlu") {
                // Left shifts
                immh_immb - esize
            } else {
                // Right shifts
                (2 * esize) - immh_immb
            };

            // Build arrangement suffixes.
            let (rd_suffix, rn_suffix) = if is_narrowing {
                // Narrowing: source is always 128-bit, dest depends on Q.
                let src_suf = shift_imm_arrangement(src_esize, 1);
                let dest_suf = shift_imm_arrangement(dest_esize, q);
                (dest_suf, src_suf)
            } else if is_widening {
                // Widening: source depends on Q, dest is always 128-bit.
                let src_suf = shift_imm_arrangement(src_esize, q);
                let dest_suf = shift_imm_arrangement(dest_esize, 1);
                (dest_suf, src_suf)
            } else {
                let suf = shift_imm_arrangement(esize, q);
                (suf, suf)
            };

            decoded.operands = vec![
                Operand::Text {
                    value: format!("v{}{}", rd, rd_suffix),
                },
                Operand::Text {
                    value: format!("v{}{}", rn, rn_suffix),
                },
                Operand::Text {
                    value: format!("#{}", shift),
                },
            ];
            return;
        }

        // Vector SIMD: rewrite Vec register operands to include arrangement suffix.
        let size = ((word >> 22) & 0x3) as u8;
        let q = ((word >> 30) & 0x1) as u8;
        let suffix = if is_fp_vector_opcode(&opcode_id) {
            fp_vec_arrangement_suffix(size, q)
        } else {
            vec_arrangement_suffix(size, q)
        };
        for op in &mut decoded.operands {
            if let Operand::Register { register } = op
                && register.architecture == ArchitectureId::AArch64
                && (64..96).contains(&register.id)
            {
                let reg_num = register.id - 64;
                *op = Operand::Text {
                    value: format!("v{}{}", reg_num, suffix),
                };
            }
        }
    } else if is_scalar_fp_integer_conversion_opcode(&opcode_id) {
        apply_scalar_fp_integer_conversion_aliases(decoded, word, &opcode_id);
    } else if is_scalar_fp_opcode(&opcode_id) {
        // Scalar FP: rewrite Vec register operands to s/d/h register names.
        let ftype = ((word >> 22) & 0x3) as u8;
        let prefix = match ftype {
            0 => 's',
            1 => 'd',
            3 => 'h',
            _ => return, // reserved ftype — leave untouched
        };
        for op in &mut decoded.operands {
            if let Operand::Register { register } = op
                && register.architecture == ArchitectureId::AArch64
                && (64..96).contains(&register.id)
            {
                let reg_num = register.id - 64;
                *op = Operand::Text {
                    value: format!("{}{}", prefix, reg_num),
                };
            }
        }
    } else {
        // General aliases for base integer, branch, and system instructions.
        apply_general_aliases(decoded, word, &opcode_id);
    }
}

fn sve_pred_pattern_name(value: u32) -> Option<&'static str> {
    match value {
        0x00 => Some("pow2"),
        0x01 => Some("vl1"),
        0x02 => Some("vl2"),
        0x03 => Some("vl3"),
        0x04 => Some("vl4"),
        0x05 => Some("vl5"),
        0x06 => Some("vl6"),
        0x07 => Some("vl7"),
        0x08 => Some("vl8"),
        0x09 => Some("vl16"),
        0x0a => Some("vl32"),
        0x0b => Some("vl64"),
        0x0c => Some("vl128"),
        0x0d => Some("vl256"),
        0x1d => Some("mul4"),
        0x1e => Some("mul3"),
        0x1f => Some("all"),
        _ => None,
    }
}

fn apply_sve_pattern_count_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let pattern = (word >> 5) & 0x1f;
    let multiplier = ((word >> 16) & 0xf) + 1;
    let rd = word & 0x1f;

    let mut operands = if opcode_id.contains("_ZPII") {
        vec![Operand::Text {
            value: format!("z{rd}.{}", sve_pattern_count_element_suffix(opcode_id)),
        }]
    } else if opcode_id.contains("_XPIWDI") {
        vec![
            Operand::Text {
                value: format!("x{rd}"),
            },
            Operand::Text {
                value: format!("w{rd}"),
            },
        ]
    } else if opcode_id.contains("_WPII") {
        vec![Operand::Text {
            value: format!("w{rd}"),
        }]
    } else {
        vec![Operand::Text {
            value: format!("x{rd}"),
        }]
    };
    if let Some(pattern_name) = sve_pred_pattern_name(pattern) {
        if pattern != 0x1f || multiplier != 1 {
            operands.push(Operand::Text {
                value: pattern_name.to_string(),
            });
        }
    } else {
        operands.push(Operand::Immediate {
            value: pattern as i64,
            unsigned_mask: 0,
        });
    }
    if multiplier != 1 {
        operands.push(Operand::Text {
            value: format!("mul #{multiplier}"),
        });
    }

    decoded.operands = operands;
    decoded.registers_read = if opcode_id.starts_with("CNT") {
        Vec::new()
    } else if opcode_id.contains("_XPIWDI") {
        vec![RegisterId::aarch64(rd), RegisterId::aarch64(rd)]
    } else if opcode_id.contains("_ZPII") {
        vec![RegisterId::aarch64(160 + rd)]
    } else {
        vec![RegisterId::aarch64(rd)]
    };
    decoded.registers_written = if opcode_id.contains("_XPIWDI") {
        vec![RegisterId::aarch64(rd), RegisterId::aarch64(rd)]
    } else if opcode_id.contains("_ZPII") {
        vec![RegisterId::aarch64(160 + rd)]
    } else {
        vec![RegisterId::aarch64(rd)]
    };
}

fn sve_pattern_count_element_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.contains('B') {
        "b"
    } else if opcode_id.contains('H') {
        "h"
    } else if opcode_id.contains('W') {
        "s"
    } else {
        "d"
    }
}

fn sve_element_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.ends_with("_B") {
        "b"
    } else if opcode_id.ends_with("_H") {
        "h"
    } else if opcode_id.ends_with("_S") {
        "s"
    } else {
        "d"
    }
}

fn sve_wider_element_suffix(opcode_id: &str) -> &'static str {
    match sve_element_suffix(opcode_id) {
        "b" => "h",
        "h" => "s",
        _ => "d",
    }
}

fn sve_narrow_halving_source_suffix(opcode_id: &str) -> Option<&'static str> {
    if opcode_id.contains("HNB_ZZZ_") || opcode_id.contains("HNT_ZZZ_") {
        Some(sve_wider_element_suffix(opcode_id))
    } else {
        None
    }
}

fn is_sve_xar_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("XAR_ZZZI_")
}

fn sve_xar_immediate(word: u32, opcode_id: &str) -> u32 {
    let imm_low = (word >> 16) & 0x7;
    match sve_element_suffix(opcode_id) {
        "b" => imm_low,
        "h" => imm_low | (((word >> 19) & 0x1) << 3),
        "s" => imm_low | (((word >> 19) & 0x3) << 3),
        _ => imm_low | (((word >> 19) & 0x3) << 3) | (((word >> 22) & 0x1) << 5),
    }
}

fn apply_sve_xar_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let element_bits = sve_shift_element_bits(opcode_id);
    let zd = word & 0x1f;
    let zm = (word >> 5) & 0x1f;
    let rotate = element_bits - sve_xar_immediate(word, opcode_id);

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zd}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zm}.{suffix}"),
        },
        Operand::Immediate {
            value: rotate as i64,
            unsigned_mask: 0,
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zd), RegisterId::aarch64(160 + zm)];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_narrow_shift_immediate_opcode(opcode_id: &str) -> bool {
    (opcode_id.ends_with("_ZZI_B")
        || opcode_id.ends_with("_ZZI_H")
        || opcode_id.ends_with("_ZZI_S"))
        && (opcode_id.starts_with("RSHRNB_")
            || opcode_id.starts_with("RSHRNT_")
            || opcode_id.starts_with("SHRNB_")
            || opcode_id.starts_with("SHRNT_")
            || opcode_id.starts_with("SQRSHRNB_")
            || opcode_id.starts_with("SQRSHRNT_")
            || opcode_id.starts_with("SQRSHRUNB_")
            || opcode_id.starts_with("SQRSHRUNT_")
            || opcode_id.starts_with("SQSHRNB_")
            || opcode_id.starts_with("SQSHRNT_")
            || opcode_id.starts_with("SQSHRUNB_")
            || opcode_id.starts_with("SQSHRUNT_")
            || opcode_id.starts_with("UQRSHRNB_")
            || opcode_id.starts_with("UQRSHRNT_")
            || opcode_id.starts_with("UQSHRNB_")
            || opcode_id.starts_with("UQSHRNT_"))
}

fn sve_narrow_shift_source_bits(opcode_id: &str) -> u32 {
    match sve_element_suffix(opcode_id) {
        "b" => 16,
        "h" => 32,
        _ => 64,
    }
}

fn apply_sve_narrow_shift_immediate_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let dst_suffix = sve_element_suffix(opcode_id);
    let src_suffix = sve_wider_element_suffix(opcode_id);
    let src_bits = sve_narrow_shift_source_bits(opcode_id);
    let immh = (word >> 19) & 0xf;
    let immb = (word >> 16) & 0x7;
    let raw = (immh << 3) | immb;
    let immediate = raw - raw.next_power_of_two() / 2;
    let shift = src_bits - immediate;
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
        Operand::Immediate {
            value: shift as i64,
            unsigned_mask: 0,
        },
    ];
    decoded.registers_read = if opcode_id.contains("RNT_") || opcode_id.contains("HNT_") {
        vec![RegisterId::aarch64(160 + zd), RegisterId::aarch64(160 + zn)]
    } else {
        vec![RegisterId::aarch64(160 + zn)]
    };
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_extract_narrow_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("SQXTNB_ZZ_")
        || opcode_id.starts_with("SQXTNT_ZZ_")
        || opcode_id.starts_with("SQXTUNB_ZZ_")
        || opcode_id.starts_with("SQXTUNT_ZZ_")
        || opcode_id.starts_with("UQXTNB_ZZ_")
        || opcode_id.starts_with("UQXTNT_ZZ_")
}

fn apply_sve_extract_narrow_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let dst_suffix = sve_element_suffix(opcode_id);
    let src_suffix = sve_wider_element_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zn)];
    if opcode_id.starts_with("SQXTNT_ZZ_")
        || opcode_id.starts_with("SQXTUNT_ZZ_")
        || opcode_id.starts_with("UQXTNT_ZZ_")
    {
        decoded
            .registers_read
            .insert(0, RegisterId::aarch64(160 + zd));
    }
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_zzz_tied_destination_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("ADCLB_ZZZ_")
        || opcode_id.starts_with("ADCLT_ZZZ_")
        || opcode_id.starts_with("SBCLB_ZZZ_")
        || opcode_id.starts_with("SBCLT_ZZZ_")
        || opcode_id.starts_with("EORBT_ZZZ_")
        || opcode_id.starts_with("EORTB_ZZZ_")
        || opcode_id.starts_with("SABA_ZZZ_")
        || opcode_id.starts_with("UABA_ZZZ_")
        || opcode_id.starts_with("SQRDMLAH_ZZZ_")
        || opcode_id.starts_with("SQRDMLSH_ZZZ_")
        || opcode_id.contains("HNT_ZZZ_")
}

fn sve_nt1_addr_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.contains("_S") { "s" } else { "d" }
}

fn apply_sve_nt1_vector_address_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let addr_suffix = sve_nt1_addr_suffix(opcode_id);
    let zt = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let pg = (word >> 10) & 0x7;
    let rm = (word >> 16) & 0x1f;
    let is_load = opcode_id.starts_with("LDNT1");
    let address = if rm == 31 {
        format!("[z{zn}.{addr_suffix}]")
    } else {
        format!("[z{zn}.{addr_suffix}, x{rm}]")
    };

    decoded.operands = vec![
        Operand::Text {
            value: format!("{{ z{zt}.{addr_suffix} }}"),
        },
        Operand::Text {
            value: if is_load {
                format!("p{pg}/z")
            } else {
                format!("p{pg}")
            },
        },
        Operand::Text { value: address },
    ];

    let mut reads = vec![RegisterId::aarch64(128 + pg), RegisterId::aarch64(160 + zn)];
    if !is_load {
        reads.push(RegisterId::aarch64(31));
    }
    if rm != 31 {
        reads.push(RegisterId::aarch64(rm));
    }
    if !is_load {
        reads.insert(0, RegisterId::aarch64(160 + zt));
    }
    decoded.registers_read = reads;
    decoded.registers_written = if is_load {
        vec![RegisterId::aarch64(160 + zt)]
    } else {
        Vec::new()
    };
}

fn apply_sve_match_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let pd = word & 0xf;
    let zn = (word >> 5) & 0x1f;
    let pg = (word >> 10) & 0x7;
    let zm = (word >> 16) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("p{pd}.{suffix}"),
        },
        Operand::Text {
            value: format!("p{pg}/z"),
        },
        Operand::Text {
            value: format!("z{zn}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zm}.{suffix}"),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(128 + pg), RegisterId::aarch64(160 + zn)];
    if zm != zn {
        decoded.registers_read.push(RegisterId::aarch64(160 + zm));
    }
    decoded.registers_written = vec![RegisterId::aarch64(128 + pd)];
}

fn apply_sve_histseg_aliases(decoded: &mut robustone_core::ir::DecodedInstruction, word: u32) {
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let zm = (word >> 16) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.b"),
        },
        Operand::Text {
            value: format!("z{zn}.b"),
        },
        Operand::Text {
            value: format!("z{zm}.b"),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zn), RegisterId::aarch64(160 + zm)];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn apply_sve_histcnt_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let pg = (word >> 10) & 0x7;
    let zm = (word >> 16) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{suffix}"),
        },
        Operand::Text {
            value: format!("p{pg}/z"),
        },
        Operand::Text {
            value: format!("z{zn}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zm}.{suffix}"),
        },
    ];
    decoded.registers_read = vec![
        RegisterId::aarch64(128 + pg),
        RegisterId::aarch64(160 + zn),
        RegisterId::aarch64(160 + zm),
    ];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn sve_pmull_destination_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.ends_with("_Q") {
        "q"
    } else {
        sve_element_suffix(opcode_id)
    }
}

fn sve_pmull_source_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.ends_with("_Q") {
        "d"
    } else if opcode_id.ends_with("_D") {
        "s"
    } else {
        "b"
    }
}

fn apply_sve_pmull_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let dst_suffix = sve_pmull_destination_suffix(opcode_id);
    let src_suffix = sve_pmull_source_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let zm = (word >> 16) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
        Operand::Text {
            value: format!("z{zm}.{src_suffix}"),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zn), RegisterId::aarch64(160 + zm)];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_indexed_mla_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("FMLA_ZZZI_")
        || opcode_id.starts_with("FMLS_ZZZI_")
        || opcode_id.starts_with("FMUL_ZZZI_")
        || opcode_id.starts_with("MLA_ZZZI_")
        || opcode_id.starts_with("MLS_ZZZI_")
        || opcode_id.starts_with("MUL_ZZZI_")
        || opcode_id.starts_with("SQDMULH_ZZZI_")
        || opcode_id.starts_with("SQRDMLAH_ZZZI_")
        || opcode_id.starts_with("SQRDMLSH_ZZZI_")
        || opcode_id.starts_with("SQRDMULH_ZZZI_")
}

fn sve_indexed_mla_destination_is_read(opcode_id: &str) -> bool {
    opcode_id.starts_with("FMLA_ZZZI_")
        || opcode_id.starts_with("FMLS_ZZZI_")
        || opcode_id.starts_with("MLA_ZZZI_")
        || opcode_id.starts_with("MLS_ZZZI_")
        || opcode_id.starts_with("SQRDMLAH_ZZZI_")
        || opcode_id.starts_with("SQRDMLSH_ZZZI_")
}

fn sve_indexed_mla_lane(opcode_id: &str, word: u32) -> (u32, u32) {
    if opcode_id.ends_with("_H") {
        (
            (word >> 16) & 0x7,
            (((word >> 22) & 0x1) << 2) | ((word >> 19) & 0x3),
        )
    } else if opcode_id.ends_with("_S") {
        ((word >> 16) & 0x7, (word >> 19) & 0x3)
    } else {
        ((word >> 16) & 0xf, (word >> 20) & 0x1)
    }
}

fn apply_sve_indexed_mla_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let (zm, lane) = sve_indexed_mla_lane(opcode_id, word);

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{suffix}"),
        },
        Operand::Text {
            value: format!("z{zm}.{suffix}[{lane}]"),
        },
    ];
    let mut reads = vec![RegisterId::aarch64(160 + zn), RegisterId::aarch64(160 + zm)];
    if sve_indexed_mla_destination_is_read(opcode_id) {
        reads.insert(0, RegisterId::aarch64(160 + zd));
    }
    decoded.registers_read = reads;
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_long_mla_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("FMLALB_ZZZI_")
        || opcode_id.starts_with("FMLALB_ZZZ_")
        || opcode_id.starts_with("FMLALT_ZZZI_")
        || opcode_id.starts_with("FMLALT_ZZZ_")
        || opcode_id.starts_with("FMLSLB_ZZZI_")
        || opcode_id.starts_with("FMLSLB_ZZZ_")
        || opcode_id.starts_with("FMLSLT_ZZZI_")
        || opcode_id.starts_with("FMLSLT_ZZZ_")
        || opcode_id.starts_with("SMLALB_ZZZI_")
        || opcode_id.starts_with("SMLALB_ZZZ_")
        || opcode_id.starts_with("SMLALT_ZZZI_")
        || opcode_id.starts_with("SMLALT_ZZZ_")
        || opcode_id.starts_with("SMLSLB_ZZZI_")
        || opcode_id.starts_with("SMLSLB_ZZZ_")
        || opcode_id.starts_with("SMLSLT_ZZZI_")
        || opcode_id.starts_with("SMLSLT_ZZZ_")
        || opcode_id.starts_with("UMLALB_ZZZI_")
        || opcode_id.starts_with("UMLALB_ZZZ_")
        || opcode_id.starts_with("UMLALT_ZZZI_")
        || opcode_id.starts_with("UMLALT_ZZZ_")
        || opcode_id.starts_with("UMLSLB_ZZZI_")
        || opcode_id.starts_with("UMLSLB_ZZZ_")
        || opcode_id.starts_with("UMLSLT_ZZZI_")
        || opcode_id.starts_with("UMLSLT_ZZZ_")
        || opcode_id.starts_with("SQDMLALB_ZZZI_")
        || opcode_id.starts_with("SQDMLALT_ZZZI_")
        || opcode_id.starts_with("SQDMLALB_ZZZ_")
        || opcode_id.starts_with("SQDMLALT_ZZZ_")
        || opcode_id.starts_with("SQDMLSLB_ZZZI_")
        || opcode_id.starts_with("SQDMLSLT_ZZZI_")
        || opcode_id.starts_with("SQDMLSLB_ZZZ_")
        || opcode_id.starts_with("SQDMLSLT_ZZZ_")
        || opcode_id.starts_with("SQDMLALBT_ZZZ_")
        || opcode_id.starts_with("SQDMLSLBT_ZZZ_")
        || opcode_id.starts_with("SABALB_ZZZ_")
        || opcode_id.starts_with("SABALT_ZZZ_")
        || opcode_id.starts_with("SABDLB_ZZZ_")
        || opcode_id.starts_with("SABDLT_ZZZ_")
        || opcode_id.starts_with("UABALB_ZZZ_")
        || opcode_id.starts_with("UABALT_ZZZ_")
        || opcode_id.starts_with("UABDLB_ZZZ_")
        || opcode_id.starts_with("UABDLT_ZZZ_")
        || opcode_id.starts_with("SADDLBT_ZZZ_")
        || opcode_id.starts_with("SADDLB_ZZZ_")
        || opcode_id.starts_with("SADDLT_ZZZ_")
        || opcode_id.starts_with("SSUBLBT_ZZZ_")
        || opcode_id.starts_with("SSUBLB_ZZZ_")
        || opcode_id.starts_with("SSUBLTB_ZZZ_")
        || opcode_id.starts_with("SSUBLT_ZZZ_")
        || opcode_id.starts_with("UADDLB_ZZZ_")
        || opcode_id.starts_with("UADDLT_ZZZ_")
        || opcode_id.starts_with("SMULLB_ZZZI_")
        || opcode_id.starts_with("SMULLT_ZZZI_")
        || opcode_id.starts_with("SMULLB_ZZZ_")
        || opcode_id.starts_with("SMULLT_ZZZ_")
        || opcode_id.starts_with("UMULLB_ZZZI_")
        || opcode_id.starts_with("UMULLT_ZZZI_")
        || opcode_id.starts_with("UMULLB_ZZZ_")
        || opcode_id.starts_with("UMULLT_ZZZ_")
        || opcode_id.starts_with("SQDMULLB_ZZZI_")
        || opcode_id.starts_with("SQDMULLT_ZZZI_")
        || opcode_id.starts_with("SQDMULLB_ZZZ_")
        || opcode_id.starts_with("SQDMULLT_ZZZ_")
}

fn sve_long_mla_destination_is_read(opcode_id: &str) -> bool {
    !opcode_id.starts_with("SABDL")
        && !opcode_id.starts_with("UABDL")
        && !opcode_id.starts_with("SADDL")
        && !opcode_id.starts_with("UADDL")
        && !opcode_id.starts_with("SSUBL")
        && !opcode_id.starts_with("USUBL")
        && !opcode_id.starts_with("SMULL")
        && !opcode_id.starts_with("UMULL")
        && !opcode_id.starts_with("SQDMULL")
}

fn sve_long_mla_destination_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.ends_with("SHH") || opcode_id.ends_with("_S") {
        "s"
    } else if opcode_id.ends_with("_H") {
        "h"
    } else {
        "d"
    }
}

fn sve_long_mla_source_suffix(opcode_id: &str) -> &'static str {
    if opcode_id.ends_with("_H") {
        "b"
    } else if opcode_id.ends_with("SHH") || opcode_id.ends_with("_S") {
        "h"
    } else {
        "s"
    }
}

fn sve_long_mla_indexed_lane(opcode_id: &str, word: u32) -> Option<(u32, u32)> {
    if !opcode_id.contains("ZZZI") {
        return None;
    }

    if opcode_id.ends_with("SHH") || opcode_id.ends_with("_S") {
        Some((
            (word >> 16) & 0x7,
            (((word >> 19) & 0x1) << 2) | (((word >> 11) & 0x1) << 1) | ((word >> 20) & 0x1),
        ))
    } else {
        Some((
            (word >> 16) & 0xf,
            (((word >> 20) & 0x1) << 1) | ((word >> 11) & 0x1),
        ))
    }
}

fn apply_sve_long_mla_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let dst_suffix = sve_long_mla_destination_suffix(opcode_id);
    let src_suffix = sve_long_mla_source_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let zm = (word >> 16) & 0x1f;
    let (zm_operand, zm_read) =
        if let Some((indexed_zm, lane)) = sve_long_mla_indexed_lane(opcode_id, word) {
            (format!("z{indexed_zm}.{src_suffix}[{lane}]"), indexed_zm)
        } else {
            (format!("z{zm}.{src_suffix}"), zm)
        };

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
        Operand::Text { value: zm_operand },
    ];
    let mut reads = vec![
        RegisterId::aarch64(160 + zn),
        RegisterId::aarch64(160 + zm_read),
    ];
    if sve_long_mla_destination_is_read(opcode_id) {
        reads.insert(0, RegisterId::aarch64(160 + zd));
    }
    decoded.registers_read = reads;
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_while_compare_opcode(opcode_id: &str) -> bool {
    (opcode_id.starts_with("WHILEGE_")
        || opcode_id.starts_with("WHILEGT_")
        || opcode_id.starts_with("WHILEHI_")
        || opcode_id.starts_with("WHILEHS_")
        || opcode_id.starts_with("WHILELE_")
        || opcode_id.starts_with("WHILELO_")
        || opcode_id.starts_with("WHILELT_")
        || opcode_id.starts_with("WHILERW_")
        || opcode_id.starts_with("WHILEWR_"))
        && (opcode_id.contains("_PWW_") || opcode_id.contains("_PXX_"))
}

fn apply_sve_while_compare_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let prefix = if opcode_id.contains("_PWW_") {
        "w"
    } else {
        "x"
    };
    let pd = word & 0xf;
    let rn = (word >> 5) & 0x1f;
    let rm = (word >> 16) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("p{pd}.{suffix}"),
        },
        Operand::Text {
            value: format_conversion_gpr_with_prefix(rn, prefix),
        },
        Operand::Text {
            value: format_conversion_gpr_with_prefix(rm, prefix),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(rn), RegisterId::aarch64(rm)];
    decoded.registers_written = vec![RegisterId::aarch64(128 + pd)];
}

fn apply_sve_tbl_two_register_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let suffix = sve_element_suffix(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let zm = (word >> 16) & 0x1f;
    let second = (zn + 1) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{suffix}"),
        },
        Operand::Text {
            value: format!("{{ z{zn}.{suffix}, z{second}.{suffix} }}"),
        },
        Operand::Text {
            value: format!("z{zm}.{suffix}"),
        },
    ];
    decoded.registers_read = vec![
        RegisterId::aarch64(160 + zn),
        RegisterId::aarch64(160 + second),
        RegisterId::aarch64(160 + zm),
    ];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

