        || opcode_id.starts_with("SSUBWB_ZZZ_")
        || opcode_id.starts_with("SSUBWT_ZZZ_")
        || opcode_id.starts_with("UADDWB_ZZZ_")
        || opcode_id.starts_with("UADDWT_ZZZ_")
        || opcode_id.starts_with("USUBWB_ZZZ_")
        || opcode_id.starts_with("USUBWT_ZZZ_")
        || opcode_id.starts_with("SADDLB_ZZZ_")
        || opcode_id.starts_with("SADDLT_ZZZ_")
        || opcode_id.starts_with("SSUBLB_ZZZ_")
        || opcode_id.starts_with("SSUBLT_ZZZ_")
        || opcode_id.starts_with("UADDLB_ZZZ_")
