fn is_sve_shift_left_long_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("SSHLLB_ZZI_")
        || opcode_id.starts_with("SSHLLT_ZZI_")
        || opcode_id.starts_with("USHLLB_ZZI_")
        || opcode_id.starts_with("USHLLT_ZZI_")
}

fn apply_sve_shift_left_long_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let dst_suffix = sve_element_suffix(opcode_id);
    let src_suffix = match dst_suffix {
        "h" => "b",
        "s" => "h",
        _ => "s",
    };
    let element_bits = match src_suffix {
        "b" => 8,
        "h" => 16,
        _ => 32,
    };
    let shift = sve_shift_imm(word, opcode_id) & (element_bits - 1);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
        Operand::Immediate {
            value: shift as i64,
            unsigned_mask: 0,
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zn)];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn is_sve_convert_long_narrow_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("FCVTLT_ZPMZ_")
        || opcode_id.starts_with("FCVTLB_ZPMZ_")
        || opcode_id.starts_with("FCVTNT_ZPMZ_")
        || opcode_id.starts_with("FCVTNB_ZPMZ_")
        || opcode_id.starts_with("FCVTXNT_ZPMZ_")
        || opcode_id.starts_with("FCVTX_ZPMZ_")
}

fn sve_convert_long_narrow_suffixes(opcode_id: &str) -> (&'static str, &'static str) {
    if opcode_id.ends_with("HTOS") {
        ("s", "h")
    } else if opcode_id.ends_with("STOD") {
        ("d", "s")
    } else if opcode_id.ends_with("STOH") {
        ("h", "s")
    } else {
        ("s", "d")
    }
}

fn apply_sve_convert_long_narrow_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let (dst_suffix, src_suffix) = sve_convert_long_narrow_suffixes(opcode_id);
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let pg = (word >> 10) & 0x7;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.{dst_suffix}"),
        },
        Operand::Text {
            value: format!("p{pg}/m"),
        },
        Operand::Text {
            value: format!("z{zn}.{src_suffix}"),
        },
    ];
    decoded.registers_read = vec![RegisterId::aarch64(160 + zd), RegisterId::aarch64(128 + pg)];
    if zn != zd {
        decoded.registers_read.push(RegisterId::aarch64(160 + zn));
    }
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

fn apply_sve_ext_vector_list_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
) {
    let zd = word & 0x1f;
    let zn = (word >> 5) & 0x1f;
    let imm8 = ((word >> 10) & 0x7) | (((word >> 16) & 0x1f) << 3);
    let next = (zn + 1) & 0x1f;

    decoded.operands = vec![
        Operand::Text {
            value: format!("z{zd}.b"),
        },
        Operand::Text {
            value: format!("{{ z{zn}.b, z{next}.b }}"),
        },
        Operand::Text {
            value: if imm8 == 0 {
                "#0".to_string()
            } else {
                format!("#0x{imm8:x}")
            },
        },
    ];
    decoded.registers_read = vec![
        RegisterId::aarch64(160 + zn),
        RegisterId::aarch64(160 + next),
    ];
    decoded.registers_written = vec![RegisterId::aarch64(160 + zd)];
}

