/// True if the opcode converts between scalar FP and integer registers.
fn is_scalar_fp_integer_conversion_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("SCVTF")
        || opcode_id.starts_with("UCVTF")
        || opcode_id.starts_with("FCVTZS")
        || opcode_id.starts_with("FCVTZU")
}

/// Apply register-width aliases for scalar FP/integer conversion instructions.
fn apply_scalar_fp_integer_conversion_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    let ftype = ((word >> 22) & 0x3) as u8;
    let fp_prefix = match ftype {
        0 => 's',
        1 => 'd',
        3 => 'h',
        _ => return,
    };
    let int_prefix = if opcode_id.contains("_X") { "x" } else { "w" };

    for op in &mut decoded.operands {
        if let Operand::Register { register } = op {
            if register.architecture != ArchitectureId::AArch64 {
                continue;
            }
            if (64..96).contains(&register.id) {
                *op = Operand::Text {
                    value: format!("{}{}", fp_prefix, register.id - 64),
                };
            } else if register.id <= 31 {
                *op = Operand::Text {
                    value: format_conversion_gpr_with_prefix(register.id, int_prefix),
                };
            }
        }
    }
}

