/// True if the opcode is a load/store instruction.
fn is_loadstore_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("LDR")
        || opcode_id.starts_with("STR")
        || opcode_id.starts_with("LDUR")
        || opcode_id.starts_with("STUR")
        || opcode_id.starts_with("LDP")
        || opcode_id.starts_with("STP")
        || opcode_id.starts_with("STXR")
        || opcode_id.starts_with("LDXR")
        || opcode_id.starts_with("STXP")
        || opcode_id.starts_with("LDXP")
        || opcode_id.starts_with("CAS")
        || opcode_id.starts_with("SWP")
        || opcode_id.starts_with("LDADD")
        || opcode_id.starts_with("PRFM")
        || opcode_id == "SIMD_LS_LOAD"
        || opcode_id == "SIMD_LS_STORE"
}

/// Apply load/store aliases: combine base+offset into memory operand text.
fn apply_loadstore_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    use robustone_core::ir::Operand;

    let ops = &mut decoded.operands;
    if opcode_id == "PRFM_LIT" || opcode_id == "PRFML" {
        let imm19 = ((word >> 5) & 0x7FFFF) as i32;
        let offset = sign_extend(imm19, 19) << 2;
        let target = (decoded.address as i64).wrapping_add(offset as i64) as u64;
        ops.clear();
        ops.push(Operand::Text {
            value: "pldl1keep".to_string(),
        });
        ops.push(Operand::Text {
            value: if target == 0 {
                "0x0".to_string()
            } else {
                format_branch_target(target)
            },
        });
        return;
    }

    if ops.len() < 2 {
        return;
    }

    // Determine register size prefix from opcode for data registers (Rt).
    let is_32bit = opcode_id.ends_with("_W")
        || opcode_id.ends_with("_B")
        || opcode_id.ends_with("_H")
        || opcode_id == "LDRSB_W"
        || opcode_id == "LDRSH_W"
        || opcode_id == "CASW";
    let data_prefix = if is_32bit { "w" } else { "x" };

    // FP/SIMD load/store: determine register prefix (s/d/q) from opcode.
    let fp_prefix = if opcode_id.ends_with("_S") || opcode_id.contains("_S_") {
        Some("s")
    } else if opcode_id.ends_with("_D") || opcode_id.contains("_D_") {
        Some("d")
    } else if opcode_id.ends_with("_Q") || opcode_id.contains("_Q_") {
        Some("q")
    } else {
        None
    };

    // Helper: format a GPR with explicit prefix.
    let fmt_reg = |id: u32, prefix: &str| -> String {
        match id {
            0..=30 => format!("{}{}", prefix, id),
            31 if prefix == "w" => "wsp".to_string(),
            31 => "sp".to_string(),
            _ => format!("r{}", id),
        }
    };

    // Helper to extract register name. Base registers are always xN.
    let reg_name = |op: &Operand| -> String {
        match op {
            Operand::Register { register } => {
                if register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    format!("v{}", register.id - 64)
                } else if register.architecture == ArchitectureId::AArch64 {
                    fmt_reg(register.id, "x")
                } else {
                    format!("r{}", register.id)
                }
            }
            _ => String::new(),
        }
    };

    // Helper to format a data register with the correct size.
    let data_reg_name = |op: &Operand| -> String {
        match op {
            Operand::Register { register } => {
                if register.architecture == ArchitectureId::AArch64
                    && (64..96).contains(&register.id)
                {
                    if let Some(prefix) = fp_prefix {
                        format!("{}{}", prefix, register.id - 64)
                    } else {
                        format!("v{}", register.id - 64)
                    }
                } else if register.architecture == ArchitectureId::AArch64 {
                    fmt_reg(register.id, data_prefix)
                } else {
                    format!("r{}", register.id)
                }
            }
            _ => String::new(),
        }
    };

    // Helper to extract immediate value.
    let imm_val = |op: &Operand| -> i64 {
        match op {
            Operand::Immediate { value, .. } => *value,
            _ => 0,
        }
    };

    let fmt_memory_offset = |offset: i64| -> String {
        if offset.abs() >= 10 {
            if offset < 0 {
                format!("-0x{:x}", -offset)
            } else {
                format!("0x{:x}", offset)
            }
        } else {
            offset.to_string()
        }
    };

    // Determine operand structure based on opcode.
    let is_pair = opcode_id.starts_with("LDP") || opcode_id.starts_with("STP");
    let is_literal =
        opcode_id.starts_with("LDR_LIT") || opcode_id == "LDRSW_LIT" || opcode_id.ends_with("_LIT");
    let is_post = opcode_id.contains("POST");
    let is_pre = opcode_id.contains("PRE");
    let is_unscaled = opcode_id.starts_with("LDUR") || opcode_id.starts_with("STUR");
    let is_reg = opcode_id.contains("REG");
    let is_excl = opcode_id.starts_with("STXR") || opcode_id.starts_with("LDXR");
    let is_cas = opcode_id.starts_with("CAS");
    let is_excl_pair = opcode_id.starts_with("STXP") || opcode_id.starts_with("LDXP");

    // Advanced SIMD load/store: register list + memory operand.
    if opcode_id == "SIMD_LS_LOAD" || opcode_id == "SIMD_LS_STORE" {
        let q = ((word >> 30) & 0x1) as u8;
        let size = ((word >> 10) & 0x3) as u8;
        let opcode = ((word >> 12) & 0xF) as u8;
        let rt = (word & 0x1F) as u8;
        let rn = ((word >> 5) & 0x1F) as u8;
        let l = ((word >> 22) & 0x1) as u8;

        let arr = vec_arrangement_suffix(size, q);
        let (mnemonic, num_regs) = match opcode {
            0x0 => (if l == 1 { "ld4" } else { "st4" }, 4),
            0x2 => (if l == 1 { "ld1" } else { "st1" }, 4),
            0x4 => (if l == 1 { "ld3" } else { "st3" }, 3),
            0x6 => (if l == 1 { "ld1" } else { "st1" }, 3),
            0x7 => (if l == 1 { "ld1" } else { "st1" }, 1),
            0x8 => (if l == 1 { "ld2" } else { "st2" }, 2),
            0xA => (if l == 1 { "ld1" } else { "st1" }, 2),
            _ => (if l == 1 { "ld1" } else { "st1" }, 1),
        };
        decoded.mnemonic = mnemonic.to_string();

        let mut list = String::new();
        list.push_str("{ ");
        for i in 0..num_regs {
            if i > 0 {
                list.push_str(", ");
            }
            list.push_str(&format!("v{}{}", rt + i as u8, arr));
        }
        list.push_str(" }");

        let base = match rn {
            0..=30 => format!("x{}", rn),
            31 => "sp".to_string(),
            _ => format!("r{}", rn),
        };

        ops.clear();
        ops.push(Operand::Text { value: list });
        ops.push(Operand::Text {
            value: format!("[{}]", base),
        });
        return;
    }

    if is_literal {
        // Literal: ldr x0, <label> — operands are [Rt, imm19]
        // Compute PC-relative target.
        let imm19 = ((word >> 5) & 0x7FFFF) as i32;
        let offset = sign_extend(imm19, 19) << 2;
        let target = (decoded.address as i64).wrapping_add(offset as i64) as u64;
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
        if ops.len() >= 2 {
            ops[1] = Operand::Text {
                value: format_literal_target(target),
            };
        }
        return;
    }

    if is_excl_pair {
        // stxp ws, wt1, wt2, [xn]
        // Status register (Rs) is always 32-bit (wN).
        if !ops.is_empty()
            && let Operand::Register { register } = &ops[0]
        {
            ops[0] = Operand::Text {
                value: fmt_reg(register.id, "w"),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
        if ops.len() > 2 {
            ops[2] = Operand::Text {
                value: data_reg_name(&ops[2]),
            };
        }
        if ops.len() >= 4 {
            let base = reg_name(&ops[3]);
            ops[3] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_cas {
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
        if ops.len() >= 3 {
            let base = reg_name(&ops[2]);
            ops[2] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_excl {
        if opcode_id.starts_with("LDXR") {
            if !ops.is_empty() {
                ops[0] = Operand::Text {
                    value: data_reg_name(&ops[0]),
                };
            }
            if ops.len() >= 2 {
                let base = reg_name(&ops[1]);
                ops[1] = Operand::Text {
                    value: format!("[{}]", base),
                };
            }
            return;
        }

        // stxr ws, wt, [xn]
        // Status register (Rs) is always 32-bit (wN).
        if !ops.is_empty()
            && let Operand::Register { register } = &ops[0]
        {
            ops[0] = Operand::Text {
                value: fmt_reg(register.id, "w"),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
        if ops.len() >= 3 {
            let base = reg_name(&ops[2]);
            ops[2] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    // Format data registers with correct size before memory operand handling.
    if is_pair {
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
    } else {
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
    }

    // For pair, normal, post, pre, unscaled, reg: memory operand is the last one or last two.
    // The format has [Rt, Rn, offset/Rm] or [Rt, Rt2, Rn, offset].
    let mem_idx = if is_pair {
        2 // Rn is at index 2 for LDP format
    } else {
        1 // Rn is at index 1 for single-register formats
    };

    if ops.len() <= mem_idx {
        return;
    }

    let base = reg_name(&ops[mem_idx]);

    if is_reg {
        // Register offset: [xn, xm]
        if ops.len() > mem_idx + 1 {
            let rm = reg_name(&ops[mem_idx + 1]);
            if !rm.is_empty() {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, {}]", base, rm),
                };
                ops.remove(mem_idx + 1);
            }
        }
        return;
    }

    if is_post {
        // Post-indexed: [xn], #offset
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            ops[mem_idx] = Operand::Text {
                value: format!("[{}], #{}", base, fmt_memory_offset(offset)),
            };
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_pre {
        // Pre-indexed: [xn, #offset]!
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            ops[mem_idx] = Operand::Text {
                value: format!("[{}, #{}]!", base, fmt_memory_offset(offset)),
            };
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]!", base),
            };
        }
        return;
    }

    if is_unscaled {
        // Unscaled: [xn, #offset] or [xn] if offset=0
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            if offset == 0 {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}]", base),
                };
            } else {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, #{}]", base, fmt_memory_offset(offset)),
                };
            }
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_pair {
        // Pair: [xn, #offset] or [xn] if offset=0
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            // Pair offset is scaled: imm7 * scale
            let scale = if opcode_id.contains("_Q") {
                16
            } else if opcode_id.contains("_X") || opcode_id.contains("_D") {
                8
            } else {
                4
            };
            let scaled = offset * scale;
            if scaled == 0 {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}]", base),
                };
            } else {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, #{}]", base, fmt_memory_offset(scaled)),
                };
            }
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    // Unsigned immediate: [xn, #offset] or [xn] if offset=0
    // Offset is scaled: imm12 * scale
    let scale = if opcode_id.ends_with("_Q") {
        16
    } else if opcode_id.ends_with("_D")
        || opcode_id.ends_with("_X")
        || opcode_id == "LDRSH_X"
        || opcode_id == "LDRSB_X"
    {
        8
    } else if opcode_id.ends_with("_S")
        || opcode_id.ends_with("W")
        || opcode_id.ends_with("H")
        || opcode_id.ends_with("B")
        || opcode_id == "LDRSB_W"
        || opcode_id == "LDRSH_W"
    {
        if opcode_id.ends_with("B") && !opcode_id.starts_with("LDRS") {
            1
        } else if opcode_id.ends_with("H") && !opcode_id.starts_with("LDRS") {
            2
        } else {
            4
        }
    } else {
        1
    };

    if ops.len() > mem_idx + 1 {
        let offset = imm_val(&ops[mem_idx + 1]);
        let scaled = offset * scale;
        if scaled == 0 {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}, #{}]", base, fmt_memory_offset(scaled)),
            };
        }
        ops.remove(mem_idx + 1);
    } else {
        ops[mem_idx] = Operand::Text {
            value: format!("[{}]", base),
        };
    }
}

/// Return the vector arrangement suffix for a modified-immediate instruction.
fn modified_imm_arrangement(cmode: u8, q: u8, op: u8) -> &'static str {
    match cmode {
        0..=7 => match q {
            0 => ".2s",
            1 => ".4s",
            _ => "",
        },
        8..=11 => match q {
            0 => ".4h",
            1 => ".8h",
            _ => "",
        },
        12..=13 => match q {
            0 => ".2s",
            1 => ".4s",
            _ => "",
        },
        14 => match (op, q) {
            (0, 0) => ".8b",
            (0, 1) => ".16b",
            (1, 0) => "", // scalar d
            (1, 1) => ".2d",
            _ => "",
        },
        15 => modified_imm_fp_arrangement(q, op),
        _ => "",
    }
}

/// Return the FP arrangement suffix for a modified-immediate FMOV.
fn modified_imm_fp_arrangement(q: u8, op: u8) -> &'static str {
    match (op, q) {
        (0, 0) => ".2s",
        (0, 1) => ".4s",
        (1, 1) => ".2d",
        _ => "",
    }
}

/// Compute the left-shift amount for a modified-immediate cmode value.
fn modified_imm_shift(cmode: u8) -> u8 {
    match cmode {
        0 | 1 | 8 | 9 => 0,
        2 | 3 | 10 | 11 => 8,
        4 | 5 => 16,
        6 | 7 => 24,
        12 => 8,
        13 => 16,
        _ => 0,
    }
}

/// Expand an 8-bit FP immediate into a `f64` value per ARM ARM.
fn fp_expand_imm(imm8: u8, op: u8, q: u8) -> f64 {
    let a = ((imm8 >> 7) & 1) as u32;
    let b = ((imm8 >> 6) & 1) as u32;
    let c = ((imm8 >> 5) & 1) as u32;
    let d = ((imm8 >> 4) & 1) as u32;
    let e = ((imm8 >> 3) & 1) as u32;
    let f = ((imm8 >> 2) & 1) as u32;
    let g = ((imm8 >> 1) & 1) as u32;
    let h = (imm8 & 1) as u32;

    let sign = a;

    if op == 1 || q == 1 {
        // Double precision
        let exp = ((1 - b) << 10)
            | (b << 9)
            | (c << 8)
            | (d << 7)
            | (b << 6)
            | (b << 5)
            | (b << 4)
            | (b << 3)
            | (b << 2)
            | (b << 1)
            | b;
        let frac =
            ((e as u64) << 51) | ((f as u64) << 50) | ((g as u64) << 49) | ((h as u64) << 48);
        let bits = ((sign as u64) << 63) | ((exp as u64) << 52) | frac;
        f64::from_bits(bits)
    } else {
        // Single precision
        let exp =
            ((1 - b) << 7) | (b << 6) | (c << 5) | (d << 4) | (b << 3) | (b << 2) | (b << 1) | b;
        let frac = (e << 22) | (f << 21) | (g << 20) | (h << 19);
        let bits = (sign << 31) | (exp << 23) | frac;
        f32::from_bits(bits) as f64
    }
}

/// Return the vector arrangement suffix (e.g. `.8b`, `.4s`) for integer SIMD.
fn vec_arrangement_suffix(size: u8, q: u8) -> &'static str {
    match (size, q) {
        (0, 0) => ".8b",
        (0, 1) => ".16b",
        (1, 0) => ".4h",
        (1, 1) => ".8h",
        (2, 0) => ".2s",
        (2, 1) => ".4s",
        (3, 1) => ".2d",
        _ => "",
    }
}

/// Return the vector arrangement suffix for FP SIMD operations.
fn fp_vec_arrangement_suffix(size: u8, q: u8) -> &'static str {
    // FP vector uses bit 22 (the lower bit of size) as element size:
    // bit 22 = 0 → S (single), bit 22 = 1 → D (double)
    let elem_size = size & 0x1;
    match (elem_size, q) {
        (0, 0) => ".2s",
        (0, 1) => ".4s",
        (1, 1) => ".2d",
        _ => "",
    }
}

/// Return the vector arrangement suffix for FP indexed-element operations.
fn fp_indexed_arrangement_suffix(size: u8, q: u8) -> &'static str {
    // FP indexed element uses size directly:
    // size=00 → FP16 (H), size=10 → S, size=11 → D
    match (size, q) {
        (0, 0) => ".4h",
        (0, 1) => ".8h",
        (2, 0) => ".2s",
        (2, 1) => ".4s",
        (3, 1) => ".2d",
        _ => "",
    }
}

/// Derive the element size (8, 16, 32, 64) from the `immh` field of a shift-immediate instruction.
fn shift_imm_esize(immh: u8) -> u8 {
    match immh {
        0b0001 => 8,
        0b0010 | 0b0011 => 16,
        0b0100..=0b0111 => 32,
        0b1000..=0b1111 => 64,
        _ => 0,
    }
}

/// Return the vector arrangement suffix for a shift-immediate instruction.
fn shift_imm_arrangement(esize: u8, q: u8) -> &'static str {
    match (esize, q) {
        (8, 0) => ".8b",
        (8, 1) => ".16b",
        (16, 0) => ".4h",
        (16, 1) => ".8h",
        (32, 0) => ".2s",
        (32, 1) => ".4s",
        (64, 1) => ".2d",
        _ => "",
    }
}

