    // -------------------------------------------------------------------------
    // Operand rendering tests
    // -------------------------------------------------------------------------
    fn operand_texts(insn: &robustone_core::ir::DecodedInstruction) -> Vec<String> {
        insn.operands
            .iter()
            .map(|op| match op {
                robustone_core::ir::Operand::Text { value } => value.clone(),
                robustone_core::ir::Operand::Register { register } => format!("r{}", register.id),
                robustone_core::ir::Operand::Immediate { value, .. } => value.to_string(),
                robustone_core::ir::Operand::Memory { base, displacement } => {
                    if let Some(base) = base {
                        format!("[r{}, #{}]", base.id, displacement)
                    } else {
                        format!("[#{}]", displacement)
                    }
                }
            })
            .collect()
    }

